#![cfg(feature = "native-image")]
use lianwall_core::{
    config::VideoDecode,
    socket::{DecoderKind, NativePhase},
};
use lianwall_daemon::native::{NativeEngine, Options};
use std::{path::PathBuf, time::Duration};

/// Run in an isolated Wayland session; fixtures are generated by run-video.py.
#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
#[ignore = "requires isolated Wayland/Vulkan and LIANWALL_NATIVE_VIDEO_FIXTURES"]
async fn native_video_loops_replacement_rollback_and_shutdown() {
    let output = std::env::var("LIANWALL_NATIVE_TEST_OUTPUT").unwrap();
    let videos = PathBuf::from(std::env::var("LIANWALL_NATIVE_VIDEO_FIXTURES").unwrap());
    let images = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("native/tests/fixtures");
    let engine = std::sync::Arc::new(NativeEngine::new().unwrap());
    let cut = Options {
        fit: 0,
        duration_ms: 0,
        fps: 60,
    };
    engine
        .show(&images.join("red.png"), &output, cut)
        .await
        .unwrap();
    let first = engine
        .show_video(&videos.join("cfr-bframes.mp4"), &output, 0)
        .await
        .unwrap();
    assert!(engine.is_active());
    assert_eq!(engine.runtime().phase, NativePhase::Running);
    assert_eq!(engine.runtime().decoder, Some(DecoderKind::Software));
    tokio::time::sleep(Duration::from_millis(2600)).await;
    let playing = engine.statistics().await.unwrap();
    assert!(
        playing.video_frames > first.video_frames + 20,
        "video must keep rendering: {playing:?}"
    );
    assert!(
        playing.video_loops >= 2,
        "natural loops must continue: {playing:?}"
    );
    assert!(
        engine
            .show_video(&videos.join("corrupt.mp4"), &output, 0)
            .await
            .is_err()
    );
    assert!(engine.is_active());
    tokio::time::sleep(Duration::from_millis(150)).await;
    let retained = engine.statistics().await.unwrap();
    assert!(
        retained.video_frames > playing.video_frames,
        "bad source must retain playback"
    );
    assert!(
        engine
            .show_video(&videos.join("vfr-bframes.mp4"), "missing-output", 1)
            .await
            .is_err()
    );
    assert!(engine.is_active());
    engine
        .show_video(&videos.join("vfr-bframes.mp4"), &output, 1)
        .await
        .unwrap();
    tokio::time::sleep(Duration::from_millis(200)).await;
    engine
        .show(&images.join("blue.png"), &output, cut)
        .await
        .unwrap();
    let still = engine.statistics().await.unwrap();
    tokio::time::sleep(Duration::from_millis(150)).await;
    assert_eq!(
        engine.statistics().await.unwrap().video_frames,
        still.video_frames
    );
    engine
        .show_video(&videos.join("cfr-bframes.mp4"), &output, 0)
        .await
        .unwrap();
    let hardware = engine
        .show_video_with_decode(&videos.join("cfr-bframes.mp4"), &output, 0, 1)
        .await
        .unwrap();
    tokio::time::sleep(Duration::from_millis(2600)).await;
    assert_eq!(engine.runtime().decoder, Some(DecoderKind::Vulkan));
    assert!(engine.runtime().fallback_reason.is_none());
    let hardware_playing = engine.statistics().await.unwrap();
    assert!(
        hardware_playing.video_hardware_frames > hardware.video_hardware_frames + 20,
        "hardware must keep presenting: {hardware_playing:?}"
    );
    assert!(
        engine
            .show_video_with_decode(&videos.join("high10.mp4"), &output, 0, 1)
            .await
            .is_err(),
        "this test GPU lacks H.264 High10"
    );
    assert!(engine.is_active());
    let fallback_stats = engine
        .show_video_with_decode(&videos.join("high10.mp4"), &output, 0, 2)
        .await
        .unwrap();
    assert!(fallback_stats.video_fallbacks > hardware_playing.video_fallbacks);
    let runtime = engine.runtime();
    assert_eq!(runtime.requested_decode, Some(VideoDecode::Auto));
    assert_eq!(runtime.decoder, Some(DecoderKind::Software));
    assert!(
        runtime
            .fallback_reason
            .as_ref()
            .is_some_and(|s| !s.is_empty())
    );
    tokio::time::sleep(Duration::from_millis(150)).await;
    let fallback_playing = engine.statistics().await.unwrap();
    assert!(fallback_playing.video_software_frames > fallback_stats.video_software_frames);
    assert_eq!(
        fallback_playing.video_hardware_frames,
        fallback_stats.video_hardware_frames
    );
    engine
        .show_video_with_decode(&videos.join("vfr-bframes.mp4"), &output, 1, 1)
        .await
        .unwrap();
    // Live crossfades through both decoder modes and both layout modes.
    let fade = Options {
        fit: 0,
        duration_ms: 400,
        fps: 30,
    };
    for decode in [0, 1] {
        let before = engine.statistics().await.unwrap();
        let faded = engine
            .show(&images.join("red.png"), &output, fade)
            .await
            .unwrap();
        assert!(
            faded.frames >= before.frames + 4,
            "video→image needs intermediate frames"
        );
        let first = engine
            .show_video_with_options(&videos.join("cfr-bframes.mp4"), &output, fade, decode)
            .await
            .unwrap();
        assert!(
            first.frames >= faded.frames + 4,
            "image→video needs intermediate frames"
        );
        let second = engine
            .show_video_with_options(
                &videos.join("vfr-bframes.mp4"),
                &output,
                Options { fit: 1, ..fade },
                1 - decode,
            )
            .await
            .unwrap();
        assert!(
            second.frames >= first.frames + 4,
            "video→video needs intermediate frames"
        );
        tokio::time::sleep(Duration::from_millis(150)).await;
        assert!(engine.statistics().await.unwrap().video_frames > second.video_frames);
    }
    // Hide must promptly cancel a running two-video fade and join both sources.
    let changing = engine.clone();
    let selected = output.clone();
    let source = videos.join("cfr-bframes.mp4");
    let pending = tokio::spawn(async move {
        changing
            .show_video_with_options(
                &source,
                &selected,
                Options {
                    duration_ms: 2000,
                    ..fade
                },
                1,
            )
            .await
    });
    let before_revision = engine.runtime().revision;
    let deadline = tokio::time::Instant::now() + Duration::from_secs(2);
    while engine.runtime().phase != NativePhase::Preparing {
        assert!(
            tokio::time::Instant::now() < deadline,
            "preparation never became observable"
        );
        tokio::time::sleep(Duration::from_millis(5)).await;
    }
    for _ in 0..10 {
        let snapshot = engine.runtime();
        assert_eq!(snapshot.phase, NativePhase::Preparing);
        assert!(snapshot.pending.is_some());
        assert!(snapshot.current.is_some());
        assert!(snapshot.revision >= before_revision);
        tokio::time::sleep(Duration::from_millis(10)).await;
    }
    tokio::time::timeout(Duration::from_secs(2), engine.hide())
        .await
        .unwrap()
        .unwrap();
    assert!(
        pending.await.unwrap().is_err(),
        "hide must cancel video fade"
    );
    engine.hide().await.unwrap();
    assert!(!engine.is_active());
    assert_eq!(engine.runtime().phase, NativePhase::Idle);
    assert!(engine.runtime().decoder.is_none());
    engine
        .show_video(&videos.join("vfr-bframes.mp4"), &output, 0)
        .await
        .unwrap();
    tokio::time::timeout(Duration::from_secs(3), engine.shutdown())
        .await
        .unwrap();
    assert!(!engine.is_active());
    assert!(
        engine
            .show_video(&videos.join("cfr-bframes.mp4"), &output, 0)
            .await
            .is_err()
    );
    // Unwinding must join the GPU owner too, rather than leave it detached
    // while the driver may be unloaded during process teardown.
    let fallback = NativeEngine::new().unwrap();
    fallback
        .show_video(&videos.join("cfr-bframes.mp4"), &output, 0)
        .await
        .unwrap();
    let unwound = tokio::task::spawn_blocking(move || {
        std::panic::catch_unwind(std::panic::AssertUnwindSafe(move || {
            let _owner = fallback;
            panic!("intentional native owner unwind probe");
        }))
    })
    .await
    .unwrap();
    assert!(unwound.is_err());
    eprintln!(
        "native production video owner stats: first={first:?}, playing={playing:?}, retained={retained:?}"
    );
}
